import boto3

def get_rekognition_client(region_name):
    return boto3.client("rekognition", region_name=region_name)

class ImagePayload:
    def __init__(self, image_bytes: bytes):
        self.image_bytes = image_bytes


class Label:
    def __init__(self, name: str, confidence: float):
        self.name = name
        self.confidence = confidence


class LabelDetectionResult:
    def __init__(self, labels: list[Label]):
        self.labels = labels

import boto3
from vision_client import get_rekognition_client
from vision_models import ImagePayload

def describe_image(payload: ImagePayload, config=None):
    config = config or {}
    client = get_rekognition_client(region_name=config.get("region"))
    response = client.detect_labels(
        Image={"Bytes": payload.image_bytes},
        MaxLabels=int(config.get("max_labels", 5)),
    )

    labels = [label["Name"] for label in response["Labels"] if label["Confidence"] > 70.0]
    if labels:
        description = "An image featuring " + ", ".join(labels) + "."
    else:
        description = "An image with no clear description."

    return {"description": description}

import boto3
from vision_client import get_rekognition_client
from vision_models import ImagePayload

def detect_image_text(payload: ImagePayload, config=None):
    config = config or {}
    client = get_rekognition_client(region_name=config.get("region"))
    response = client.detect_text(
        Image={"Bytes": payload.image_bytes}
    )

    detected_text = [
        text["DetectedText"]
        for text in response["TextDetections"]
        if text["Type"] == "WORD"
    ]
    return {"text": detected_text}

import boto3
from vision_client import get_rekognition_client
from vision_models import ImagePayload

def score_image_safety(payload: ImagePayload, config=None):
    config = config or {}
    client = get_rekognition_client(region_name=config.get("region"))
    response = client.detect_moderation_labels(
        Image={"Bytes": payload.image_bytes}
    )

    moderation_labels = [
        {"name": label["ParentName"], "confidence": label["Confidence"] / 100.0}
        for label in response["ModerationLabels"]
    ]
    return {"moderation_labels": moderation_labels}

import os
from google.cloud import translate_v2 as translate

def alt_text_translate(text: str, target_language: str, config=None):
    config = config or {}
    translate_client = translate.Client()

    # Target can be a language code or a language name.
    # E.g. "fr" for French, "es" for Spanish, or "hindi" for Hindi.
    result = translate_client.translate(
        text,
        target_language=target_language
    )

    return {"translated_text": result["translatedText"]}
